    #[serde(default, skip_serializing_if = "Vec::is_empty")]
    allowed_uri_sans: Vec<String>,
    #[serde(default, skip_serializing_if = "Vec::is_empty")]
    allowed_organizational_units: Vec<String>,
    #[serde(default, skip_serializing_if = "Vec::is_empty")]
    required_extensions: Vec<String>,
    #[serde(default, skip_serializing_if = "Vec::is_empty")]
