struct JwtMountState {
    config: Option<JwtConfig>,
    roles: BTreeMap<String, JwtRole>,
    identities: BTreeMap<String, ExternalIdentity>,
    replay: BTreeMap<String, u64>,
    #[serde(default, skip_serializing_if = "is_false")]
