    #[cfg(test)]
    pub(super) fn authorize_request_parameters(
        &self,
        principal: &Principal,
        namespace: &str,
        method: &str,
        path: &str,
        body: &Value,
        now: u64,
    ) -> Result<(), AuthError> {
