    ) -> Result<RadiusLoginPlan, AuthError> {
        self.prepare_radius_login_with_path(namespace, mount, None, method, body, now)
    }

    #[cfg(test)]
    pub(crate) fn prepare_radius_login_with_path(
        &self,
        namespace: &str,
        mount: &str,
        path_username: Option<&str>,
        method: &str,
        body: &Value,
        now: u64,
    ) -> Result<RadiusLoginPlan, AuthError> {
